/**
 * Appendix C of the format spec: frozen fingerprint vectors.
 *
 * These values are generated by the script embedded in the spec. If this test
 * fails, either the encoder/field order changed (update the spec and re-freeze)
 * or an implementation detail drifted silently.
 */

import { describe, expect, it } from 'vitest';
import {
  containerFingerprint,
  encodeFields,
  importDeviceKey,
  observationBinding,
  sendFingerprint,
  type SendInput,
} from '../fingerprint';

const KEY_ID = '11111111-1111-4111-8111-111111111111';
const URL = 'https://api.example.com/v1/models';

const base = (headers: SendInput['headers'] = []): SendInput => ({
  keyId: KEY_ID,
  resolvedHref: URL,
  auth: { mode: 'bearer' },
  headers,
});

const ANTHROPIC = [{ name: 'anthropic-version', value: '2023-06-01' }];
const TWO = [
  { name: 'x-a', value: '1' },
  { name: 'x-b', value: '2' },
];
const TWO_CHANGED = [
  { name: 'x-a', value: '9' },
  { name: 'x-b', value: '2' },
];

const DEVICE_KEY_RAW = new Uint8Array(32).fill(1);

describe('appendix C · send_fingerprint', () => {
  it('A: no static headers', async () => {
    expect(await sendFingerprint(base())).toBe(
      'afa884e9b5ed46f0fc618ca01380b46b137490a8a410be4aef8a925fe8775ef0'
    );
  });

  it('B: one static header', async () => {
    expect(await sendFingerprint(base(ANTHROPIC))).toBe(
      'bd83358e6e327d053cb8d34969b62055bb75c22ad6c4a835cb94368f9f25b961'
    );
  });

  it('C: two static headers', async () => {
    expect(await sendFingerprint(base(TWO))).toBe(
      'f160ca880706c2ad731448cb13b9f365b8bf476f98b85da55d2cfd47af42a62b'
    );
  });

  it('C′: the same headers in the other order produce the same value', async () => {
    const reversed = [TWO[1], TWO[0]];
    expect(await sendFingerprint(base(reversed))).toBe(
      await sendFingerprint(base(TWO))
    );
  });

  it('D: changing one header value changes the value', async () => {
    expect(await sendFingerprint(base(TWO_CHANGED))).toBe(
      '67b405140d7f4c4cb2b6c21a5faf5943048638c9ddc6d648aff229f22ceb9808'
    );
    expect(await sendFingerprint(base(TWO_CHANGED))).not.toBe(
      await sendFingerprint(base(TWO))
    );
  });

  it('negative vector: skipping the sort must not match C', async () => {
    // Encoding in insertion order is the bug the sorting rule exists to catch.
    const fields = [
      ['key', KEY_ID],
      ['url', URL],
      ['method', 'GET'],
      ['carrier', 'header'],
      ['target', 'authorization'],
      ['encoding', 'bearer'],
      ['header', 'x-b', '2'],
      ['header', 'x-a', '1'],
    ] as const;
    const prefix = new TextEncoder().encode('keya/send/1\n');
    const body = encodeFields(fields as never);
    const merged = new Uint8Array(prefix.length + body.length);
    merged.set(prefix, 0);
    merged.set(body, prefix.length);
    const digest = await crypto.subtle.digest('SHA-256', merged);
    const hex = Array.from(new Uint8Array(digest), (b) =>
      b.toString(16).padStart(2, '0')
    ).join('');
    expect(hex).toBe(
      'a535478af3843a842ef9b88d75a94544600570bf65e70c47d97df9c596231141'
    );
  });
});

describe('appendix C · container_fingerprint', () => {
  it('salt 00..0f', async () => {
    const salt = new Uint8Array([...Array(16).keys()]);
    expect(await containerFingerprint(salt)).toBe(
      '6b8f5293afa31b9045dca8013ad352cee993639aafe4062018a904f5460fd18e'
    );
  });
});

describe('appendix C · observation_binding', () => {
  it('binds the secret and the interpreter version', async () => {
    const deviceKey = await importDeviceKey(DEVICE_KEY_RAW);

    expect(
      await observationBinding(deviceKey, {
        ...base(),
        secret: 'sk-synthetic-1',
        interpreterId: 'custom/1',
      })
    ).toBe('cd5b6dcd0d9e0fcbcc102e59476e5ab4c90f9d19beaf3dbd00fbe039ceb86b7f');

    expect(
      await observationBinding(deviceKey, {
        ...base(),
        secret: 'sk-synthetic-2',
        interpreterId: 'custom/1',
      })
    ).toBe('cd1baded1b20ddea8c4fc465fed0c3f89c3b7f52ea4ae8f7f0503d53c31b11b6');
  });
});

describe('fingerprint contract', () => {
  it('changing the secret keeps the send fingerprint but moves the binding', async () => {
    const deviceKey = await importDeviceKey(DEVICE_KEY_RAW);
    const first = { ...base(), secret: 'sk-one', interpreterId: 'custom/1' };
    const second = {
      ...base(),
      secret: 'sk-two',
      interpreterId: 'custom/1',
    };

    expect(await sendFingerprint(first)).toBe(await sendFingerprint(second));
    expect(await observationBinding(deviceKey, first)).not.toBe(
      await observationBinding(deviceKey, second)
    );
  });

  it('changing the destination moves both', async () => {
    const deviceKey = await importDeviceKey(DEVICE_KEY_RAW);
    const first = { ...base(), secret: 'sk', interpreterId: 'custom/1' };
    const second = {
      ...first,
      resolvedHref: 'https://api.example.com/v2/models',
    };

    expect(await sendFingerprint(first)).not.toBe(
      await sendFingerprint(second)
    );
    expect(await observationBinding(deviceKey, first)).not.toBe(
      await observationBinding(deviceKey, second)
    );
  });

  it('changing only the interpreter version keeps the send fingerprint', async () => {
    const deviceKey = await importDeviceKey(DEVICE_KEY_RAW);
    const first = { ...base(), secret: 'sk', interpreterId: 'custom/1' };
    const second = { ...first, interpreterId: 'custom/2' };

    expect(await sendFingerprint(first)).toBe(await sendFingerprint(second));
    expect(await observationBinding(deviceKey, first)).not.toBe(
      await observationBinding(deviceKey, second)
    );
  });

  it('the encoder is length-prefixed, so separators in values stay unambiguous', () => {
    const withColon = encodeFields([['header', 'x:y', 'v']]);
    const split = encodeFields([['header', 'x', 'y:v']]);
    expect(Array.from(withColon)).not.toEqual(Array.from(split));
  });
});
